{
  "verdict": "request_changes",
  "summary": "Candidate implementation reverses the sorted list, breaking stability for tickets with equal priority.",
  "findings": [
    {
      "finding_id": "queue_order_stability",
      "file": "candidate.py",
      "line_start": 2,
      "line_end": 2,
      "severity": "high",
      "description": "The implementation reverses the sorted list after sorting by priority, which breaks the required stability for tickets with equal priority. Equal priority tickets must preserve their original relative order, but reversing the list inverts that order.",
      "evidence": "Example: queue_order([('t1',5),('t2',5),('t3',3)]) returns ['t2','t1','t3'] but should be ['t1','t2','t3']."
    }
  ]
}
